// Build fast lookup indices
window.MOS_EX_INDEX = {};
window.MOS_EX_BY_MUSCLE = {};
window.MOS_EX_BY_EQUIP = {};

MOS_EXERCISE_MASTER.forEach(function(ex) {
  MOS_EX_INDEX[ex.n.toLowerCase()] = ex;
  if (!MOS_EX_BY_MUSCLE[ex.p]) MOS_EX_BY_MUSCLE[ex.p] = [];
  MOS_EX_BY_MUSCLE[ex.p].push(ex);
  if (!MOS_EX_BY_EQUIP[ex.eq]) MOS_EX_BY_EQUIP[ex.eq] = [];
  MOS_EX_BY_EQUIP[ex.eq].push(ex);
});

// Extend existing EXERCISE_POOLS dynamically with all master exercises
if (typeof EXERCISE_POOLS !== 'undefined') {
  Object.keys(MOS_EX_BY_MUSCLE).forEach(function(m) {
    if (!EXERCISE_POOLS[m]) EXERCISE_POOLS[m] = [];
    MOS_EX_BY_MUSCLE[m].forEach(function(ex) {
      if (EXERCISE_POOLS[m].indexOf(ex.n) < 0) {
        EXERCISE_POOLS[m].push(ex.n);
      }
    });
  });
}
